using System;using System.Drawing;using System.IO;using System.Windows.Forms;using UCSPyayStudentRegistration.Helpers;using UCSPyayStudentRegistration.Queries;
namespace UCSPyayStudentRegistration.Forms { public class FrmWelcome:StyledForm {
 public FrmWelcome(){Text="University Student Registration System";ClientSize=new Size(1182,653);MinimumSize=new Size(900,620);StartPosition=FormStartPosition.CenterScreen;BackColor=Color.White;var outer=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,RowCount=1,BackColor=Color.White};outer.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,2));outer.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,96));outer.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,2));var content=new Panel{Dock=DockStyle.Fill,BackColor=Color.White};outer.Controls.Add(content,1,0);Controls.Add(outer);var hero=new PictureBox{Dock=DockStyle.Top,Height=315,SizeMode=PictureBoxSizeMode.StretchImage,BackColor=Color.FromArgb(214,232,245)};hero.Image=LoadConfigured("UniversityPhotoPath","UniversityCampus.png");content.Controls.Add(hero);var overlay=new Panel{Parent=hero,BackColor=Color.FromArgb(205,225,239),Location=new Point(170,35),Size=new Size(790,132)};var title=new Label{Text=Setting("UniversityName","University of Computer Studies, Pyay"),Dock=DockStyle.Top,Height=78,Font=new Font("Segoe UI",24,FontStyle.Bold),TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.FromArgb(23,66,105),BackColor=Color.Transparent};var motto=new Label{Text="—  Explore  •  Learn  •  Innovate  •  Succeed  —",Dock=DockStyle.Fill,Font=new Font("Bookman Old Style",12,FontStyle.Bold),TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.FromArgb(35,70,95),BackColor=Color.Transparent};overlay.Controls.Add(motto);overlay.Controls.Add(title);var logo=new PictureBox{Parent=hero,Location=new Point(18,22),Size=new Size(145,145),SizeMode=PictureBoxSizeMode.Zoom,BackColor=Color.White,Image=LoadConfigured("UniversityLogoPath","UniversityLogo.jpg")};logo.BringToFront();overlay.BringToFront();var intro=new Panel{Dock=DockStyle.Top,Height=150,BackColor=Color.White};var welcome=new Label{Text="Welcome to University of Computer Studies, Pyay",Dock=DockStyle.Top,Height=55,Font=new Font("Segoe UI",15,FontStyle.Bold),TextAlign=ContentAlignment.BottomCenter,ForeColor=Color.FromArgb(26,68,104)};var info=new Label{Text="Student Online Registration System  •  Academic Year "+Setting("AcademicYear","2026-2027")+"\r\nBegin a new registration, check your application status, or sign in to the administration portal.",Dock=DockStyle.Fill,Font=new Font("Segoe UI",10.5F),TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.FromArgb(60,70,78)};intro.Controls.Add(info);intro.Controls.Add(welcome);content.Controls.Add(intro);intro.BringToFront();var buttons=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=4,RowCount=1,Padding=new Padding(22,10,22,18),BackColor=Color.White};for(int i=0;i<4;i++)buttons.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,25));buttons.Controls.Add(Tile("Student Registration","Start a new application",delegate{new FrmRegistration().ShowDialog(this);}),0,0);buttons.Controls.Add(Tile("Registration Status","Track an application",delegate{new FrmRegistrationStatus().ShowDialog(this);}),1,0);buttons.Controls.Add(Tile("Admin Login","Open administration",delegate{new FrmAdminLogin().ShowDialog(this);}),2,0);buttons.Controls.Add(Tile("Exit","Close the program",delegate{Close();}),3,0);content.Controls.Add(buttons);buttons.BringToFront(); }
 string Setting(string key,string fallback){try{string value=new SystemSettingsQuery().Get(key);return string.IsNullOrWhiteSpace(value)?fallback:value;}catch{return fallback;}}Image LoadConfigured(string key,string fallbackName){string path=Setting(key,"");if(!File.Exists(path))path=Path.Combine(Application.StartupPath,"Resources",fallbackName);if(!File.Exists(path))return null;using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read))using(var image=Image.FromStream(stream))return new Bitmap(image);}Control Tile(string text,string hint,EventHandler click){var panel=new Panel{Dock=DockStyle.Fill,Margin=new Padding(10),BackColor=Color.FromArgb(235,243,249)};var button=new Button{Text=text,Dock=DockStyle.Top,Height=52,Font=new Font("Segoe UI",11,FontStyle.Bold),BackColor=Color.FromArgb(49,119,174),ForeColor=Color.White,FlatStyle=FlatStyle.Flat};button.FlatAppearance.BorderSize=0;button.Click+=click;var label=new Label{Text=hint,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.FromArgb(63,77,87)};panel.Controls.Add(label);panel.Controls.Add(button);return panel;}
} }
